function beta_rf_fail(string $msg, int $code = 400): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
if (isset($_GET['edit']) || (isset($_GET['ajax_action']) && $_GET['ajax_action'] !== 'list')) beta_rf_fail('Unknown action.');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $bP = fn($k) => (string) ($_POST[$k] ?? '');
    $bA = $bP('action');
    if (!in_array($bA, ['create', 'edit', 'start', 'draw', 'delete'], true)) beta_rf_fail('Unknown action.');
    if ($bA !== 'create') {
        if (!preg_match('/^\d{1,10}$/', $bP('raffle_id'))) beta_rf_fail('Raffle not found.');
        $bid = (int) $bP('raffle_id'); $st = $db->prepare('SELECT status FROM raffles WHERE id = ? LIMIT 1'); $st->bind_param('i', $bid); $st->execute();
        $bRow = $st->get_result()->fetch_assoc(); $st->close();
        if (!$bRow) beta_rf_fail('Raffle not found.', 404);
        $need = ['edit' => 'scheduled', 'start' => 'scheduled', 'draw' => 'running'][$bA] ?? null;
        if ($need && $bRow['status'] !== $need) beta_rf_fail($bA === 'draw' ? 'Only running raffles can be drawn.' : ($bA === 'start' ? 'Only scheduled raffles can be started.' : 'Only scheduled raffles can be edited.'), 409);
    }
    if ($bA === 'create' || $bA === 'edit') {
        $n = trim($bP('name')); $p = trim($bP('prize'));
        if ($n === '' || mb_strlen($n) > 255 || preg_match('/[\x00-\x1F\x7F]/u', $n)) beta_rf_fail('Raffle name must be 1 to 255 characters on one line.');
        if ($p === '' || mb_strlen($p) > 1000 || preg_match('/[\x00-\x09\x0B\x0C\x0E-\x1F\x7F]/u', $p)) beta_rf_fail('Prize must be 1 to 1000 characters.');
        if (!preg_match('/^\d{1,3}$/', $bP('number_of_winners')) || (int) $bP('number_of_winners') < 1 || (int) $bP('number_of_winners') > 100) beta_rf_fail('Number of winners must be 1 to 100.');
        foreach (['weighted', 'exclude_mods', 'subscribers_only', 'followers_only', 'followers_min_enabled'] as $k) if (isset($_POST[$k]) && $bP($k) !== '1') beta_rf_fail('Invalid on/off value.');
        if (isset($_POST['weighted'])) foreach (['weight_sub_t1' => 'Tier 1', 'weight_sub_t2' => 'Tier 2', 'weight_sub_t3' => 'Tier 3', 'weight_vip' => 'VIP'] as $k => $l)
            if (!preg_match('/^\d{1,3}(\.\d{1,2})?$/', $bP($k)) || (float) $bP($k) < 1 || (float) $bP($k) > 100) beta_rf_fail("$l weight must be 1 to 100 (two decimals).");
        if (isset($_POST['followers_only'], $_POST['followers_min_enabled'])) {
            if (!preg_match('/^\d{1,4}$/', $bP('followers_min_value')) || (int) $bP('followers_min_value') < 1 || (int) $bP('followers_min_value') > 1000) beta_rf_fail('Minimum follow time must be 1 to 1000.');
            if (!in_array($bP('followers_min_unit'), ['days', 'weeks', 'months', 'years'], true)) beta_rf_fail('Choose a follow time unit.');
        }
    }
