$bFail = [t('raffles_msg_invalid_name'), t('raffles_msg_create_failed'), t('raffles_msg_start_failed'), t('raffles_msg_not_found'), t('raffles_msg_no_entries'), t('raffles_msg_pick_failed'), t('raffles_msg_update_failed'), t('raffles_msg_edit_not_scheduled'), t('raffles_msg_delete_failed'), t('raffles_msg_save_winners_failed', ['database error'])];
$bOk = $message !== '' && !in_array($message, $bFail, true);
